const rect = overlay.getBoundingClientRect();
const area = { x: rect.width * 0.2, y: rect.height * 0.2, width: rect.width * 0.6, height: rect.height * 0.6 };
const frame = document.createElement('div');
frame.style.cssText = 'position:absolute;border:1px dashed #7fd8ff;background:#2f8cff22;left:' + area.x + 'px;top:' + area.y + 'px;width:' + area.width + 'px;height:' + area.height + 'px';
overlay.append(frame);
const refs = viewer.picking.box(area, { mode: 'entity', match: 'intersect' });
if (refs.length) viewer.scene.setEntityOutline({ entities: refs.map(r => r.entityId), color: '7fd8ffff' });
return refs;
`)},{id:"operate.boxSelect",title:"鼠标框选实体",api:"viewer.picking.startBoxSelect",description:"进入框选模式，在三维视图中拖出矩形；运行其他示例会结束框选。",code:pe(`
