await viewer.scene.add(new sdk.HeatMap({ points: { features }, heatMapStyle: { brushDiameter: 3, blendMode: 'max', colorMapping: { valueArray: [20, 50, 80], colorArray: ['00ffff', 'ffff00', 'ff0000'] } } }));
await viewer.camera.flyTo({ id: 'h', name: 'h', position: [0, 16, 12], target: [0, 0, 0] }, 600);
`)},{id:"heatmap.update",title:"实时更新热力点",api:"heatmap.update({ points })",description:"每秒刷新一次热力数据。",code:pe(`
