setInterval(() => { heat.update({ points: { features: make() } }).catch(e => log.error(e)); }, 1000);
log('热力数据每秒刷新，运行其他示例时停止');
`)},{id:"heatmap.delete",title:"删除热力图",api:"heatmap.delete",description:"添加后删除。",code:pe(`
